  {
   "id": "perpetual_confidentiality_undefined",
   "severity": "medium",
   "message": "Confidentiality lasts indefinitely and 'confidential information' is not defined, which may make it hard to enforce against the Employee.",
   "quote": "The Employee must not disclose the Company's confidential information. This applies during and after employment."
  },
  {
   "id": "at_will_vs_ontario_law",
   "severity": "medium",
   "message": "At-will employment is a U.S. concept, but the agreement is governed by Ontario law, where employees generally have statutory and common-law notice and severance rights. The at-will clause may be unenforceable, creating termination cost exposure for Northwind.",
   "quote": "Employment is at-will. Either Party may end it at any time."
  },
  {
   "id": "template_clauses_mismatch",
   "severity": "low",
   "message": "The agreement contains commercial-style clauses (mutual insurance, mutual warranties, non-solicit of 'Personnel', force majeure) that do not fit an employment relationship. They create ambiguity about the Company's obligations, such as insurance and warranties owed to the Employee.",
   "quote": "Each Party must maintain, at its own cost:"
  },
  {
   "id": "no_employee_non_compete_or_clear_ip_scope",
   "severity": "low",
   "message": "The IP assignment covers anything created 'during employment' without limiting it to work-related inventions, and there is no moral rights waiver. This may be challenged. The non-solicit is also vague and mutual.",
   "quote": "The Employee assigns to the Company all right, title and interest in any inventions and intellectual property created during employment."
  },
  {
   "id": "dispute_resolution_vague",
   "severity": "low",
   "message": "The dispute clause is vague (an undefined 'Business Days' term and no clear escalation or notice mechanism), and it conflicts somewhat with the exclusive Ontario courts clause.",
   "quote": "If the dispute is not resolved within twenty Business Days, either Party may pursue the remedies available to it."
  }
 ],
